# Situations supplémentaires : Administrateur réseau et Cybersécurité (pour atteindre 40 chacune)
from cards import O

def C(track, title, text, a_label, a_out, b_label, b_out):
    return dict(track=track, title=title, text=text, options=[(a_label, a_out), (b_label, b_out)])

